import java.lang.reflect.*;

interface UserService { String login(String u); }
class UserServiceImpl implements UserService {
    public String login(String u) { return "welcome " + u; }
}
class BeforeHandler implements InvocationHandler {
    private Object target;
    BeforeHandler(Object t) { target = t; }
    public Object invoke(Object proxy, Method m, Object[] args) throws Throwable {
        System.out.println("[before] calling " + m.getName());
        return m.invoke(target, args);
    }
}
public class Main {
    public static void main(String[] a) throws Exception {
        UserService real = new UserServiceImpl();
        UserService proxy = (UserService) Proxy.newProxyInstance(
            UserService.class.getClassLoader(),
            new Class[]{UserService.class},
            new BeforeHandler(real));
        System.out.println(proxy.login("alice"));
    }
}
